-- Autogenerated Hyprland Lua Config for MacBook (Intel Graphics)
hl.config({ autogenerated = true })

-- MONITORS
hl.monitor({ output = "eDP-1", mode = "1920x1080@60.03", position = "0x0", scale = 1 })
hl.monitor({ output = "HDMI-A-1", mode = "1920x1200@59.95", position = "-1920x0", scale = 1 })

-- MY PROGRAMS
local terminal = "kitty"
local fileManager = "kitty -e yazi"
local menu = "rofi -show drun"

-- AUTOSTART
hl.on("hyprland.start", function()
    hl.exec_cmd("firefox", { workspace = "2", silent = true })
    hl.exec_cmd("spotify", { workspace = "3", silent = true })
    hl.exec_cmd("kitty", { workspace = "special:magic", silent = true })

    hl.exec_cmd("gsettings set org.gnome.desktop.interface color-scheme 'prefer-dark'")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface gtk-theme 'Adwaita-dark'")

    hl.exec_cmd("swaybg -i ~/Pictures/Iusearchwallpaper.png -m fill")
    hl.exec_cmd("waybar")
    hl.exec_cmd("nm-applet --indicator &")
    hl.exec_cmd("blueman-applet &")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")

    hl.exec_cmd("swayosd-libinput-backend")
    hl.exec_cmd("dunst")
    hl.exec_cmd("udiskie &")

    hl.exec_cmd("hyprctl setcursor Bibata-Modern-Classic 24")
end)

-- ENVIRONMENT VARIABLES
hl.env("GTK_THEME", "Adwaita:dark")
hl.env("XCURSOR_THEME", "Bibata-Modern-Classic")
hl.env("XCURSOR_SIZE", "24")
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("GDK_BACKEND", "wayland,x11")
hl.env("_JAVA_AWT_WM_NONREPARENTING", "1")

